class Solution {
public:
    vector<int> searchRange(vector<int>& nums, int target) {
        int size = nums.size();
        int start = 0;
        int end = size-1;

        vector<int>ans={-1,-1};

        while(start<=end){
            int mid = start+(end-start)/2;

            if(nums[mid] == target){
                if(nums[mid-1] == target){
                    int j = mid-1;
                    while(nums[j] == target){
                        if(nums[j] != target){
                            ans[0]=j+1;
                            break;
                        }
                        j--;
                    } 
                    ans[1]=mid;
                }

                else if(nums[mid+1] == target){
                    int k = mid+1;
                    while(nums[k] == target){
                        if(nums[k] != target){
                            ans[1]=k-1;
                            break;
                        }
                        k++;
                    } 
                    ans[0]=mid;
                }

            }

            else if(nums[mid]<target){
                start = mid+1;
            }

            else{
                end = mid-1;
            }
        }

        return ans;

    }
};
